CREATE PROCEDURE [dbo].[SMS_OutputVoucher_ADD]
(
	@OutputVoucherCode nvarchar(50) = null,
	@OutputTypeID int = 0,
	@OutputOrderID bigint = 0,
	@InputVoucherID bigint = 0,
	@OutputDate datetime = 0,
	@OutputUser bigint = 0,
	@ReceiptUser bigint = 0,
	@OutputStoreID int = 0,
	@Working nvarchar(150) = null,
	@ReceivedUser bigint = 0,
	@PartnerID bigint = 0,
