		[PlanOutputDate],
		[MakeVoucherDate],
		[PaymentMethodID],
		[Saler],
		[FromAccountID],
		[ToAccountID],
		[PayExpiredID],
		[TotalPackedCount],
		[ExpiredDate],
		[PlanDeliveryDate],
		[DeliveryDate],
		[DeliveryUser],
		[DeliveryDesc],
		[ReceivedDate],
		[IsFinish],
		[DeliveryCost1],
		[DeliveryCost2],
		[DeliveryCost3],
		[MoneyDeliveryUser],
		[VehicleOrderIndex],
		[DistanceID],
		[BulkyID],
		[StatusID],
