		@IsRealOutput,
		@IsRetailOutput,
		@IsLayawaySale,
		@PayExpiredDate,
		@Description,
		@IsCanceled,
		@CancelReason,
		@IsReviewed,
		@ReviewComment,
		@ReviewUser,
		@ReviewDate,
		@IsLocked,
		@CreatedUser,
		@ContactID,
		@DeliveryAddress,
		@VehicleID,
		@VehicleID1,
		@PlanOutputDate,
		@MakeVoucherDate,
		@PaymentMethodID,
		@Saler,
		@FromAccountID,
		@ToAccountID,
		@PayExpiredID,
		@TotalPackedCount,
		@ExpiredDate,
		@PlanDeliveryDate,
		@DeliveryDate,
		@DeliveryUser,
		@DeliveryDesc,
		@ReceivedDate,
		@IsFinish,
		@DeliveryCost1,
		@DeliveryCost2,
		@DeliveryCost3,
		@MoneyDeliveryUser,
		@VehicleOrderIndex,
		@DistanceID,
		@BulkyID,
		@StatusID,
		@HandlerEmployeeID,
		@LastestHistoryID,
		@ProcessID,
		@WorkerOrderIndex,
		@StudentID,
		@ReviewComment1
	)
	SELECT SCOPE_IDENTITY()
END

