if (dtbData != null && dtbData.Rows.Count > 0)
{
    string strItemID = ",";
    foreach (DataRow drw in dtbData.Rows)
        strItemID += drw["ItemID"].ToString() + ",";
    strItemID += ",";

    if (strItemID.Length > 2)
    {
        DataTable dtbInStock = itemOutputVoucherEditing.GetDataTable("SMS_GetInStockByItems",
            "@StoreID", uStore.StoreID,
            "@ItemIDList", strItemID,
            "@Date", dtmOutputDate.EditValue);

        if (dtbInStock == null)
        {
            MessageManager.Error("Việc kiểm tra tồn kho bị lỗi!");
            itemOutputVoucherEditing.RollBackTransaction();
            return false;
        }

        // tạo dictionary tra cứu nhanh tồn kho theo ItemID
        Dictionary<string, decimal> dicInStock = new Dictionary<string, decimal>();
        foreach (DataRow drwStock in dtbInStock.Rows)
        {
            string strItemKey = Convert.ToString(drwStock["ItemID"]);
            decimal decInStock = Convert.ToDecimal(drwStock["InStock"]);
            if (!dicInStock.ContainsKey(strItemKey))
                dicInStock.Add(strItemKey, decInStock);
        }

        // so sánh số lượng xuất với tồn kho từng dòng
        string strWarning = "";
        foreach (DataRow drw in dtbData.Rows)
        {
            if (drw["IsDeleted"].ToString() == "0" &&
                (drw["IsSelected"].ToString() == "" || Convert.ToBoolean(drw["IsSelected"])))
            {
                string strItemKey = Convert.ToString(drw["ItemID"]);
                decimal decQuantity = Convert.ToDecimal(drw["Quantity"]);

                if (dicInStock.ContainsKey(strItemKey))
                {
                    decimal decInStock = dicInStock[strItemKey];
                    if (decQuantity > decInStock)
                    {
                        strWarning += String.Format("  - {0} ({1}): Tồn = {2}, Đang xuất = {3}\n",
                            Convert.ToString(drw["ItemCode"]),
                            Convert.ToString(drw["ItemName"]),
