                }
                else
                {
                    if (decQuantity > 0)
                    {
                        strWarning += String.Format("  - {0} ({1}): Tồn = 0, Đang xuất = {2}\n",
                            Convert.ToString(drw["ItemCode"]),
                            Convert.ToString(drw["ItemName"]),
                            decQuantity);
                    }
                }
            }
        }

        if (strWarning != "")
        {
            MessageManager.Warning("Các vật tư sau vượt quá tồn kho hiện tại:\n" + strWarning);
            itemOutputVoucherEditing.RollBackTransaction();
            return false;
        }
    }
}

